-- Modify "order_items" table
ALTER TABLE `order_items` ADD COLUMN `social_purchase_snapshot` longtext NOT NULL, ADD COLUMN `social_schema` json NULL;
-- Modify "products" table
ALTER TABLE `products` ADD COLUMN `social_schema` json NULL;
-- Create "social_operations" table
CREATE TABLE `social_operations` (`id` varchar(64) NOT NULL, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `task_id` varchar(64) NOT NULL, `operation_id` varchar(64) NOT NULL, `action` varchar(255) NOT NULL, `status` varchar(255) NOT NULL DEFAULT "pending", `upstream_operation_id` varchar(255) NOT NULL DEFAULT "", `submit_started` bool NOT NULL DEFAULT 0, `amount_cents` bigint NOT NULL DEFAULT 0, `reference` varchar(255) NOT NULL DEFAULT "", `operator_id` bigint unsigned NOT NULL DEFAULT 0, `reason` varchar(255) NOT NULL DEFAULT "", `attempts` bigint NOT NULL DEFAULT 0, `error_code` varchar(255) NOT NULL DEFAULT "", PRIMARY KEY (`id`), UNIQUE INDEX `socialoperation_task_id_operation_id` (`task_id`, `operation_id`), INDEX `socialoperation_task_id_status` (`task_id`, `status`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "social_quotes" table
CREATE TABLE `social_quotes` (`id` varchar(64) NOT NULL, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `role` varchar(255) NOT NULL DEFAULT "wholesale", `account_id` bigint unsigned NOT NULL DEFAULT 0, `user_id` bigint unsigned NOT NULL DEFAULT 0, `product_id` bigint unsigned NOT NULL, `connection_id` bigint unsigned NOT NULL, `connection_identity` varchar(255) NOT NULL DEFAULT "", `connection_revision` varchar(255) NOT NULL DEFAULT "", `product_revision` bigint NOT NULL DEFAULT 0, `schema_revision` varchar(255) NOT NULL, `pricing_revision` varchar(255) NOT NULL DEFAULT "", `upstream_product_id` varchar(255) NOT NULL, `params_json` longtext NOT NULL, `params_cipher` blob NULL, `schema_json` longtext NOT NULL, `supply_quote_id` varchar(255) NOT NULL DEFAULT "", `currency` varchar(255) NOT NULL DEFAULT "CNY", `amount_cents` bigint NOT NULL, `cost_cents` bigint NOT NULL DEFAULT 0, `expires_at` bigint NOT NULL, `consumed_by` varchar(255) NOT NULL DEFAULT "", PRIMARY KEY (`id`), INDEX `socialquote_expires_at` (`expires_at`), INDEX `socialquote_role_account_id_user_id_product_id` (`role`, `account_id`, `user_id`, `product_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "social_tasks" table
CREATE TABLE `social_tasks` (`id` varchar(64) NOT NULL, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `role` varchar(255) NOT NULL DEFAULT "wholesale", `supply_order_id` bigint unsigned NOT NULL DEFAULT 0, `order_id` bigint unsigned NOT NULL DEFAULT 0, `order_item_id` bigint unsigned NOT NULL DEFAULT 0, `account_id` bigint unsigned NOT NULL DEFAULT 0, `user_id` bigint unsigned NOT NULL DEFAULT 0, `product_id` bigint unsigned NOT NULL DEFAULT 0, `connection_id` bigint unsigned NOT NULL, `connection_identity` varchar(255) NOT NULL DEFAULT "", `connection_revision` varchar(255) NOT NULL DEFAULT "", `quote_id` varchar(255) NOT NULL, `schema_revision` varchar(255) NOT NULL, `request_no` varchar(64) NOT NULL, `request_hash` varchar(64) NOT NULL, `request_json` longtext NOT NULL, `request_cipher` blob NULL, `upstream_product_id` varchar(255) NOT NULL, `upstream_order_id` varchar(255) NOT NULL DEFAULT "", `upstream_operation_id` varchar(255) NOT NULL DEFAULT "", `phase` varchar(255) NOT NULL DEFAULT "purchase", `state` varchar(255) NOT NULL DEFAULT "pending", `submit_started` bool NOT NULL DEFAULT 0, `submit_started_at` bigint NOT NULL DEFAULT 0, `version` bigint NOT NULL DEFAULT 1, `upstream_version` bigint NOT NULL DEFAULT 0, `snapshot_cipher` blob NULL, `currency` varchar(255) NOT NULL DEFAULT "CNY", `charged_amount` bigint NOT NULL DEFAULT 0, `cost_cents` bigint NOT NULL DEFAULT 0, `settlement_state` varchar(255) NOT NULL DEFAULT "paid", `refunded_amount` bigint NOT NULL DEFAULT 0, `refund_reference` varchar(255) NOT NULL DEFAULT "", `retail_paid_amount` bigint NOT NULL DEFAULT 0, `retail_refunded_amount` bigint NOT NULL DEFAULT 0, `retail_refund_state` varchar(255) NOT NULL DEFAULT "none", `refund_id` bigint unsigned NOT NULL DEFAULT 0, `can_cancel` bool NOT NULL DEFAULT 0, `can_refill` bool NOT NULL DEFAULT 0, `next_run_at` bigint NOT NULL DEFAULT 0, `lease_until` bigint NOT NULL DEFAULT 0, `lease_token` varchar(255) NOT NULL DEFAULT "", `attempts` bigint NOT NULL DEFAULT 0, `last_error` varchar(255) NOT NULL DEFAULT "", PRIMARY KEY (`id`), INDEX `socialtask_account_id` (`account_id`), INDEX `socialtask_connection_id_upstream_order_id` (`connection_id`, `upstream_order_id`), UNIQUE INDEX `socialtask_role_account_id_request_no` (`role`, `account_id`, `request_no`), INDEX `socialtask_role_order_item_id` (`role`, `order_item_id`), INDEX `socialtask_role_phase_next_run_at_lease_until` (`role`, `phase`, `next_run_at`, `lease_until`), INDEX `socialtask_role_supply_order_id` (`role`, `supply_order_id`), INDEX `socialtask_subsite_id_user_id_order_id` (`subsite_id`, `user_id`, `order_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
